using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
public class CPHInline {
 private static readonly object StateLock=new object();
 private const string ConfigKey="portable.audioRouting.config",StateKey="portable.audioRouting.state";
 private string Arg(string key){return args.ContainsKey(key)&&args[key]!=null?args[key].ToString().Trim():"";}
 private string Read(string key){return CPH.GetGlobalVar<string>(key,true)??"";}
 private JObject DefaultConfig(){return new JObject{["version"]=2,["gameAudioVodSafe"]=true,["sourceRouting"]=new JObject()};}
 private JObject Config(){string raw=Read(ConfigKey);return raw==""?DefaultConfig():Normalize(JObject.Parse(raw),DefaultConfig());}
 private JObject Normalize(JObject input,JObject fallback){var c=(JObject)fallback.DeepClone();if(input["gameAudioVodSafe"]!=null){if(input["gameAudioVodSafe"].Type!=JTokenType.Boolean)throw new Exception("Game VOD preference must be a boolean.");c["gameAudioVodSafe"]=input["gameAudioVodSafe"];}if(input["sourceRouting"]!=null){var supplied=input["sourceRouting"] as JObject;if(supplied==null)throw new Exception("Source routing must be an object.");var routes=new JObject();foreach(var property in supplied.Properties()){if(property.Name==""||property.Value.Type!=JTokenType.String)throw new Exception("Invalid source classification.");string group=(string)property.Value;if(group=="unmanaged")continue;if(!new[]{"liveOnly","vodSafe","game"}.Contains(group))throw new Exception("Unknown source classification.");routes[property.Name]=group;}c["sourceRouting"]=routes;}c["version"]=2;return c;}
 private JObject Previous(){string raw=Read(StateKey);try{return raw==""?new JObject():JObject.Parse(raw)["payload"] as JObject??new JObject();}catch{return new JObject();}}
 private void Publish(JObject p,string mode,string status,string error="",bool terminal=true){string raw=Read(StateKey);long revision=raw==""?1:((long?)JObject.Parse(raw)["revision"]??0)+1;p["moduleVersion"]="2.0.0";p["serverTimeMs"]=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();p["operation"]=new JObject{["requestId"]=Arg("requestId"),["mode"]=mode,["status"]=status,["error"]=error};if(terminal&&Arg("requestId")!="")p["lastRequestId"]=Arg("requestId");var e=new JObject{["schemaVersion"]=1,["feature"]="audioRouting",["type"]="state",["revision"]=revision,["payload"]=p};string json=e.ToString(Formatting.None);CPH.SetGlobalVar(StateKey,json,true);try{CPH.WebsocketBroadcastJson(json);}catch{}}
 private JObject Request(string type,JObject data=null){if(!CPH.ObsIsConnected())throw new Exception("OBS is disconnected.");var response=JObject.Parse(CPH.ObsSendRaw(type,(data??new JObject()).ToString(Formatting.None),0));if((bool?)response["requestStatus"]?["result"]==false||(string)response["status"]=="error")throw new Exception("OBS rejected "+type+".");return response["responseData"] as JObject??response["data"] as JObject??response;}
 private JObject Mask(JObject mask){if(mask==null)throw new Exception("Audio tracks are unavailable.");var copy=new JObject();for(int i=1;i<=6;i++){string key=i.ToString();if(mask[key]==null||mask[key].Type!=JTokenType.Boolean)throw new Exception("Audio-track response is incomplete.");copy[key]=(bool)mask[key];}return copy;}
 private JObject Wanted(string group,bool gameSafe){var mask=new JObject();for(int i=1;i<=6;i++)mask[i.ToString()]=i==1||i==2&&(group=="vodSafe"||group=="game"&&gameSafe);return mask;}
 private JArray TrackList(JObject mask){return new JArray(Enumerable.Range(1,6).Where(i=>(bool)mask[i.ToString()]));}
 private bool AudioKind(string kind,JObject settings){return new[]{"wasapi_output_capture","wasapi_input_capture","wasapi_process_output_capture","ffmpeg_source","dshow_input"}.Contains(kind)||(bool?)settings["reroute_audio"]==true||(bool?)settings["capture_audio"]==true;}
 private JObject Inventory(JObject c){var sources=new JArray();var issues=new JArray();var known=new HashSet<string>(StringComparer.Ordinal);var errors=new HashSet<string>(StringComparer.Ordinal);bool available=false;string error="";try{var inputs=Request("GetInputList")["inputs"] as JArray;if(inputs==null)throw new Exception("OBS input inventory is unavailable.");available=true;foreach(JObject input in inputs){string name=(string)input["inputName"]??"";if(name=="")continue;known.Add(name);try{var response=Request("GetInputSettings",new JObject{["inputName"]=name});var settings=response["inputSettings"] as JObject??new JObject();string kind=(string)input["unversionedInputKind"]??(string)input["inputKind"]??(string)response["inputKind"]??"";if(!AudioKind(kind,settings))continue;var mask=Mask(Request("GetInputAudioTracks",new JObject{["inputName"]=name})["inputAudioTracks"] as JObject);sources.Add(new JObject{["name"]=name,["kind"]=kind,["tracks"]=TrackList(mask),["group"]=(string)c["sourceRouting"]?[name]??"unmanaged",["target"]=(string)settings["window"]??(string)settings["device_id"]??"",["available"]=true});}catch{errors.Add(name);issues.Add(new JObject{["name"]=name,["error"]="Input details or audio tracks are unavailable."});if(!CPH.ObsIsConnected())throw new Exception("OBS disconnected during inventory.");}}}catch(Exception ex){available=false;error=ex.Message;}
  var present=new HashSet<string>(sources.OfType<JObject>().Select(s=>(string)s["name"]),StringComparer.Ordinal);var missing=new JArray();foreach(var route in ((JObject)c["sourceRouting"]).Properties())if(!present.Contains(route.Name))missing.Add(new JObject{["name"]=route.Name,["group"]=route.Value,["tracks"]=TrackList(Wanted((string)route.Value,(bool)c["gameAudioVodSafe"])),["available"]=false,["reason"]=errors.Contains(route.Name)?"inventory_error":known.Contains(route.Name)?"ineligible":"not_found"});
  return new JObject{["config"]=c,["obsAvailable"]=available,["obsError"]=error,["liveTrack"]=1,["vodTrack"]=2,["sources"]=sources,["missingSources"]=missing,["inventoryErrors"]=issues,["results"]=new JArray()};
 }
 private string Apply(JObject c,JObject state){var results=new JArray();state["results"]=results;if((bool?)state["obsAvailable"]!=true)throw new Exception("Preferences saved; OBS is unavailable and no routing was applied.");var available=new HashSet<string>(((JArray)state["sources"]).OfType<JObject>().Select(s=>(string)s["name"]),StringComparer.Ordinal);bool failed=false;foreach(var route in ((JObject)c["sourceRouting"]).Properties()){var wanted=Wanted((string)route.Value,(bool)c["gameAudioVodSafe"]);var result=new JObject{["name"]=route.Name,["tracks"]=TrackList(wanted)};results.Add(result);if(!available.Contains(route.Name)){result["status"]="skipped";result["error"]="Source is unavailable or ineligible; OBS was not changed.";continue;}try{Request("SetInputAudioTracks",new JObject{["inputName"]=route.Name,["inputAudioTracks"]=wanted});var actual=Mask(Request("GetInputAudioTracks",new JObject{["inputName"]=route.Name})["inputAudioTracks"] as JObject);if(!JToken.DeepEquals(actual,wanted))throw new Exception("OBS track readback does not match the requested route.");result["status"]="applied";}catch(Exception ex){failed=true;result["status"]="failed";result["error"]=ex.Message;}}
  return failed?"partial":"ok";
 }
 public bool Execute(){lock(StateLock){JObject state=null;string mode=Arg("audioRoutingMode");try{if(!new[]{"initialize","refresh","save","apply","toggle"}.Contains(mode))throw new Exception("Unknown audio-routing operation.");var previous=Previous();if(Arg("requestId")!=""&&(string)previous["lastRequestId"]==Arg("requestId"))return true;var c=Config();if(mode=="save"||mode=="apply"){string json=Arg("configJson");if(json=="")throw new Exception("Audio configuration JSON is required.");c=Normalize(JObject.Parse(json),c);}if(mode=="toggle")c["gameAudioVodSafe"]=!((bool)c["gameAudioVodSafe"]);
  // Persist intent before any OBS mutation. Initialization may create empty defaults.
  if(mode=="save"||mode=="apply"||mode=="toggle"||Read(ConfigKey)=="")CPH.SetGlobalVar(ConfigKey,c.ToString(Formatting.None),true);
  state=Inventory(c);if(mode=="apply"||mode=="toggle"){Publish((JObject)state.DeepClone(),mode,"running",terminal:false);string status=Apply(c,state);var results=state["results"];state=Inventory(c);state["results"]=results;if((bool?)state["obsAvailable"]!=true)status="partial";Publish(state,mode,status,status=="partial"?"Some managed sources could not be applied or the final inventory is unavailable.":"");}else Publish(state,mode,"ok");return true;
 }catch(Exception ex){try{if(state==null)state=Previous();state["results"]=state["results"]??new JArray();Publish(state,mode,"error",ex.Message);}catch{}CPH.LogError("[audio-routing] Operation failed; inspect the private audio-routing status.");return true;}}}
}
